insert into public.admin_help_items(help_key,title_fa,body_fa,title_en,body_en,warning_fa,warning_en) values
('projects.video','ویدیو در پروژه','ویدیوها می‌توانند همراه تصاویر داخل گالری پروژه قرار بگیرند و ترتیب نمایش آن‌ها قابل جابه‌جایی است. برای هر ویدیو می‌توان Caption و Poster جدا تعیین کرد.','Video in a project','Videos can be mixed with images in the project gallery and reordered. Each video can have its own caption and poster.',null,null),
('projects.video.poster','پوستر دستی ویدیو','پوستر تصویری است که قبل از پخش ویدیو دیده می‌شود. اگر پوستر دستی انتخاب کنید، بر Thumbnail خودکار اولویت دارد. برای نتیجه بهتر تصویری با نسبت نزدیک به خود ویدیو انتخاب کنید.','Manual video poster','The poster is shown before playback. A manually selected poster overrides the automatic thumbnail. For best results, choose an image with a similar aspect ratio to the video.',null,null),
('projects.video.thumbnail','Thumbnail خودکار ویدیو','اگر پوستر دستی انتخاب نشده باشد، سیستم هنگام آپلود تلاش می‌کند از حدود ثانیه ۱ ویدیو یک تصویر JPEG بسازد و به‌عنوان Thumbnail ذخیره کند. اگر استخراج فریم ممکن نباشد، خود Player نمای اولیه ویدیو را نمایش می‌دهد.','Automatic video thumbnail','If no manual poster is selected, the uploader attempts to capture a JPEG frame from around the 1-second mark and save it as the thumbnail. If frame extraction fails, the video player falls back to its own initial frame.',null,null),
('media.video.upload','آپلود ویدیو','در حال حاضر MP4، WebM و MOV تا سقف تعیین‌شده قابل آپلود هستند. سیستم همزمان تلاش می‌کند Thumbnail خودکار بسازد و آن را به ویدیو متصل کند. برای ویدیوهای بسیار سنگین در آینده از سرویس Streaming/CDN استفاده می‌شود.','Upload video','MP4, WebM and MOV are currently accepted up to the configured limit. The system also attempts to generate and link an automatic thumbnail. Very large videos should later be served through a streaming/CDN service.','فایل ویدیویی سنگین می‌تواند مصرف Storage و پهنای باند را بالا ببرد. قبل از آپلود فایل‌های بزرگ، نسخه بهینه‌شده تهیه کنید.','Large video files can significantly increase storage and bandwidth usage. Optimize large videos before uploading.')
